import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Çerçeve stili, fotoğrafın havasını değiştirir. Minimal çerçeve sade, Polaroid çerçeve nostaljik, galeri çerçevesi zarif görünür.</p>\n<p>Doğru stil, fotoğrafı yüceltir. Yanlış stil ise görseli boğar ve dikkati dağıtır.</p>\n<p>Bu yazı, en yaygın çerçeve stillerini, her birinin nerede işe yaradığını ve renk ile gölge kurallarını anlatıyor.</p>\n<h2 id=\"why-frames-matter\">Çerçeveler neden önemlidir?</h2>\n<p>Çerçeve, fotoğrafı sayfadan ayırır. Göz, çerçeveli görseli daha kolay bulur.</p>\n<p>Çerçeve, tarza işaret eder. Minimal çerçeve modern, Polaroid çerçeve retro his verir.</p>\n<p>Çerçeve, tutarlılık yaratır. Aynı çerçeve, bir dizi fotoğrafı birleştirir.</p>\n<h2 id=\"minimal-frames\">Minimal çerçeveler: az, çoktur</h2>\n<p>Minimal çerçeve, ince beyaz ya da siyah banttır. Fotoğraf ön plandadır; çerçeve görünmez.</p>\n<p>Bu stil, portföy ve galerilerde kullanılır. Sade görünüm, fotoğrafın konuşmasına izin verir.</p>\n<p>Minimal çerçeve, her fotoğrafta işe yarar. Güvenli ve zamansız bir seçimdir.</p>\n<h2 id=\"polaroid-and-retro\">Polaroid ve retro çerçeveler</h2>\n<p>Polaroid stilinin alameti, alttaki geniş beyaz banttır; bu bant, el yazısı bir not için hazır boşluk bırakır.</p>\n<p>Bu çerçeve stili, izleyene eski albüm hissi verir; anı fotoğrafları ve davetiyeler onun doğal alanıdır.</p>\n<p>Retro çerçeveler, eski film görünümünü taklit eder. Renkli bantlar ve dokular kullanılır.</p>\n<h2 id=\"gallery-frames\">Galeri çerçeveleri: paspartu görünümü</h2>\n<p>Galeri çerçevesi, geniş beyaz boşluk kullanır. Fotoğraf, boşluğun ortasında durur.</p>\n<p>Bu stil, sanat fotoğraflarında kullanılır. Boşluk, görsele nefes aldırır.</p>\n<p>Galeri çerçevesi, baskıda en iyi görünür. Duvara asılan fotoğraflarda zarif durur.</p>\n<h2 id=\"gradient-and-glow\">Degrade ve parıltılı çerçeveler</h2>\n<p>Degrade çerçevede renkler birbirine akarak geçer; ortaya çıkan parlaklık, görsele modern bir dokunuş verir.</p>\n<p>Bu stil, sosyal medyada genç kitle arasında çok tutuyor; enerjik görsellerde çerçeveyi öne çıkarıyor.</p>\n<p>Degrade çerçevede ölçüyü kaçırmayın; aşırı canlı renkler, fotoğrafın kendisini gölgede bırakır.</p>\n<h2 id=\"frames-for-social\">Sosyal medya için çerçeveler</h2>\n<p>Akışta çerçeveli kareler hemen fark edilir; özellikle beyaz çerçeve, kalabalık arasında görseli öne taşır.</p>\n<p>Çerçevede incelik kuraldır; kalın çerçeve, küçük ekranda fotoğrafın kendisine ayrılan alanı daraltır.</p>\n<p>Profilinizde her gönderide aynı çerçeveyi sürdürün; bu tutarlılık, takipçilerinizin karelerinizi anında tanımasını sağlar.</p>\n<h2 id=\"frames-for-print\">Baskı için çerçeveler</h2>\n<p>Baskıda galeri çerçevesi zarif görünür. Geniş beyaz boşluk, fotoğrafa nefes aldırır.</p>\n<p>Baskıya göndermeden çerçeveyi son kez gözden geçirin; boyutla uyumsuz bir çerçeve, baskıda yarım çıkar.</p>\n<p>Baskı için hangi çerçeve stilinin istendiğini önceden sorun; matbaanın kesim payı, ince bir çerçeveyi bile yutabilir.</p>\n<h2 id=\"frames-for-products\">Ürün fotoğrafları için çerçeveler</h2>\n<p>Ürün çekimlerinde çerçeve sade kalmalı; beyaz çerçeve, ürünün kendisini vitrinin yıldızı yapar.</p>\n<p>Ürün kataloğunda her görselde aynı çerçeveyi koruyun; tekdüze liste, mağazaya derli toplu bir vitrin havası verir.</p>\n<p>Ürün karelerinde çerçeveyi ince bırakın; kalın bir çerçeve, ürünü olduğundan küçük gösterir.</p>\n<h2 id=\"frames-for-portraits\">Portreler için çerçeveler</h2>\n<p>Portrelerde ince çerçeve kullanın. Yüz ön planda olmalıdır; çerçeve geri planda kalmalıdır.</p>\n<p>Siyah çerçeve, portrede dramatik görünür. Beyaz çerçeve, sade ve temiz durur.</p>\n<p>Portre çerçevesini abartmayın. Çerçeve, yüzü gölgede bırakmamalıdır.</p>\n<h2 id=\"frames-for-screenshots\">Ekran görüntüleri için çerçeveler</h2>\n<p>Ekran görüntüleri çerçeveli daha düzenli görünür. İnce beyaz çerçeve kullanın.</p>\n<p>Çerçeveyi eklemeden önce gereksiz alanları kırpın. Yalnızca ilgili bölüm kalmalıdır.</p>\n<p>Ekran görüntülerini PNG biçiminde indirin. Yazılar kayıpsız kalır.</p>\n<h2 id=\"colour-theory\">Çerçeveler için renk teorisi</h2>\n<p>Beyaz çerçeve, hemen her karede işe yarayan zamansız bir klasiktir; sade görünümü fotoğrafı öne çıkarır.</p>\n<p>Siyah çerçeve, dramatik bir görünüm verir. Portre ve galeri fotoğraflarında kullanılır.</p>\n<p>Fotoğraftan bir renk seçin. Çerçeve, fotoğrafla uyumlu olmalıdır.</p>\n<h2 id=\"shadow-and-depth\">Gölge ve derinlik</h2>\n<p>Gölge, çerçeveye derinlik katar. Fotoğraf sayfadan yükselmiş gibi görünür.</p>\n<p>Hafif gölge tercih edin. Koyu gölge, görseli ağır gösterir.</p>\n<p>Gölgeli çerçeveler için PNG kullanın. JPG, yumuşak gölgeyi sert gösterir.</p>\n<h2 id=\"rounded-vs-square\">Yuvarlak ve kare çerçeveler</h2>\n<p>Yuvarlak köşeler, modern görünür. Uygulama ve web tasarımlarında yaygındır.</p>\n<p>Keskin köşeler, klasik görünür. Galeri ve baskıda kare köşe tercih edilir.</p>\n<p>Seçim, tarza bağlıdır. Modern görünüm için yuvarlak, klasik görünüm için kare kullanın.</p>\n<h2 id=\"mixing-frame-and-border\">Çerçeveleri diğer düzenlemelerle birleştirmek</h2>\n<p>Çerçeve, kırpma ve metinle birleştirilebilir. Önce kırpın, sonra çerçeveleyin, en son metin ekleyin.</p>\n<p>Sıralama önemlidir. Yanlış sıra, gereksiz iş çıkarır.</p>\n<p>Düzenlemelerin tamamı bitince indirin. Ara adımlarda indirmek, kalite kaybına yol açar.</p>\n<h2 id=\"trends-vs-timeless\">Trendler ve zamansız çerçeveler</h2>\n<p>Degrade parıltı, bugünün trendidir. Yarın modası geçebilir.</p>\n<p>Beyaz ve siyah çerçeve zamansızdır. On yıl sonra da iyi görünür.</p>\n<p>Arşiv için zamansız çerçeve kullanın. Trend, sosyal medyada kalmalıdır.</p>\n<h2 id=\"choosing-cheat-sheet\">Çerçeve seçmek: hızlı kılavuz</h2>\n<p>Sosyal medya: ince beyaz çerçeve. Portre: ince siyah çerçeve. Baskı: galeri çerçevesi.</p>\n<p>Ürün: ince beyaz çerçeve. Anı: Polaroid çerçeve. Genç kitle: degrade parıltı.</p>\n<p>Bu listeyi kaydedin. Her çerçevede yeniden düşünmek zaman kaybıdır.</p>\n<h2 id=\"frames-for-events\">Etkinlik duyuruları için çerçeveler</h2>\n<p>Etkinlik duyurularında çerçeve dikkat çeker. Renkli çerçeve, duyuruyu akışta öne çıkarır.</p>\n<p>Çerçeveyi etkinlik temasına uydurun. Renk, etkinliğin havasını yansıtmalıdır.</p>\n<p>Metni çerçevenin içine değil, fotoğrafın üzerine koyun. Çerçeve, metni taşımaz.</p>\n<p>Özetle: stil fotoğrafa uymalı, fotoğrafı boğmamalıdır. Adımlar için <a href=\"/tr/blog/gorsele-cerceve-nasil-eklenir\">Görsele çerçeve nasıl eklenir</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-cerceve-olusturucu-rehberi\">Görsel çerçeve oluşturucu kılavuzunda</a>. Köşeler için <a href=\"/tr/gorsel-kose-yuvarla\">köşe yuvarlama</a> hazırdır; araç ise <a href=\"/tr/gorsel-cerceve-olusturucu\">görsel çerçeve oluşturucu</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Instagram gönderileri için en iyi çerçeve stili hangisi?","answer":"İnce beyaz çerçeve en iyisidir; kalabalık akışta dikkat çeker ve fotoğrafı öne çıkarır. Çerçeveyi yüzde 2-3 ince tutun. Tüm gönderilerde aynı çerçeveyi kullanın; tutarlılık profilinizi tanınır kılar."},{"question":"Polaroid çerçeveyi ne zaman kullanmalıyım?","answer":"Anı fotoğrafları, davetiyeler ve nostaljik görseller için. Polaroid çerçevesi altta geniş beyaz bant ister; alt banda tarih ya da kısa not yazılabilir. Kare fotoğraflarda en iyi görünür."},{"question":"Degrade parıltılı çerçeveler profesyonel mi?","answer":"Bağlama göre değişir. Sosyal medya ve genç kitle için evet; kurumsal ve baskı işleri için hayır. Kurumsal görsellerde beyaz ya da siyah çerçeve kullanın. Degrade çerçeveyi abartmayın."},{"question":"Basılı fotoğraflar için en iyi çerçeve stili hangisi?","answer":"Galeri çerçevesi; geniş beyaz boşluk fotoğrafa nefes aldırır ve duvarda zarif görünür. Baskıdan önce çerçeveyi kontrol edin; çerçeve baskı boyutuna uymalıdır."},{"question":"Tüm ürün fotoğraflarım aynı çerçeveyi kullanmalı mı?","answer":"Evet. Tutarlı çerçeve, mağazada profesyonel görünüm yaratır. İnce beyaz çerçeve kullanın; kalın çerçeve ürünü küçültür. Çerçeve sade olmalıdır; ürün ön planda kalmalıdır."},{"question":"Yuvarlak köşeler her çerçeve stiliyle uyumlu mu?","answer":"Çoğuyla evet. Yuvarlak köşeler modern görünür; Polaroid ve minimal stillerle iyi gider. Galeri çerçevesinde keskin köşe daha klasiktir. Çerçeve ve fotoğraf yarıçapını birlikte ayarlayın."}];
